let revisionRequestSequence = 0;
function closeRevisionLesson() {
  revisionRequestSequence++;
  const dialog = document.getElementById("revision-dialog");
  if (!dialog) return;
  if (dialog.open && typeof dialog.close === "function") dialog.close();
  dialog.remove();
}
function renderExerciseRevisionLinks(exercise) {
  const ids =
    revisionCatalog.exerciseLinks[currentTrack]?.[exId(exercise)] || [];
  const lessons = ids
    .map((id) =>
      revisionCatalog.lessons.find(
        (l) => l.id === id && l.track === currentTrack,
      ),
    )
    .filter(Boolean);
  if (!lessons.length) return;
  const section = document.createElement("section");
  section.id = "exercise-revision-links";
  section.className = "revision-links";
  section.setAttribute("aria-label", "Fiches utiles pour cet exercice");
  const title = document.createElement("span");
  title.className = "revision-links-label";
  title.textContent = "Fiches utiles";
  section.append(title);
  for (const lesson of lessons) {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "revision-link";
    button.dataset.lessonId = lesson.id;
    button.textContent = lesson.title;
    button.addEventListener("click", () => openRevisionLesson(lesson.id));
    section.append(button);
  }
  statementEl.before(section);
}
async function openRevisionLesson(id) {
  if (trueExamMode || learningMode) return;
  const lesson = revisionCatalog.lessons.find(
    (l) => l.id === id && l.track === currentTrack,
  );
  if (!lesson) return;
  closeRevisionLesson();
  const request = ++revisionRequestSequence;
  const dialog = document.createElement("dialog");
  dialog.id = "revision-dialog";
  dialog.setAttribute("aria-labelledby", "revision-dialog-title");
  const header = document.createElement("div");
  header.className = "revision-dialog-header";
  const title = document.createElement("h2");
  title.id = "revision-dialog-title";
  title.textContent = lesson.title;
  const close = document.createElement("button");
  close.type = "button";
  close.textContent = "Fermer la fiche";
  close.addEventListener("click", closeRevisionLesson);
  header.append(title, close);
  const content = document.createElement("article");
  content.className = "markdown-viewer revision-dialog-content";
  content.textContent = "Chargement de la fiche…";
  dialog.append(header, content);
  document.body.append(dialog);
  dialog.addEventListener("close", () => {
    revisionRequestSequence++;
    dialog.remove();
  });
  if (typeof dialog.showModal === "function") dialog.showModal();
  else {
    dialog.setAttribute("open", "");
    close.focus();
  }
  try {
    const md = await revisionMarkdown(lesson);
    if (
      request !== revisionRequestSequence ||
      !dialog.isConnected ||
      trueExamMode ||
      learningMode
    )
      return;
    content.innerHTML = markdownToHtml(md);
    highlightMarkdownCode(content);
  } catch (error) {
    if (request === revisionRequestSequence && dialog.isConnected)
      content.textContent =
        "Impossible de charger cette fiche. Vérifie les fichiers locaux puis réessaie.";
  }
}

/* Source: frontend/app/learning.js */
async function fetchTextResource(path) {
  const url = buildLearningUrl(path);
  const res = await fetch(url);
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  return res.text();
}

function buildLearningUrl(path) {
  const normalized = (path || "").replace(/^\//, "");
  const encodedPath = encodeURI(normalized).replace(/#/g, "%23");
  try {
    return new URL("/" + encodedPath, window.location.origin).toString();
  } catch {
    return "/" + encodedPath;
  }
}

function normalizeLesson(raw, idx) {
  if (!raw || typeof raw !== "object") return null;
  const id =
    raw.id ||
    raw.ID ||
    raw.slug ||
    raw.name ||
    `lesson-${String(idx + 1).padStart(2, "0")}`;
  const title =
    raw.title || raw.Title || raw.name || raw.id || `Leçon ${idx + 1}`;
  const path = raw.path || raw.url || raw.file || raw.href;
  if (!path) return null;
  const slug = raw.slug || slugify(title || id);
  return { id, title, path, slug, track: raw.track || "go" };
}

function renderLearningContent(md) {
  if (!learningContentEl) return;
  const html = markdownToHtml(md || defaultLessonMsg);
  learningContentEl.innerHTML = html || defaultLessonMsg;
  highlightMarkdownCode(learningContentEl);
  revealPanel(learningContentEl);
}

function renderLearningLessons() {
  if (!learningLessonsEl) return;
  learningLessonsEl.innerHTML = "";

  const header = document.createElement("div");
  header.className = "header";
  const title = document.createElement("div");
  title.textContent = `Fiches ${{ go: "Go", js: "JavaScript", rust: "Rust", java: "Java" }[currentTrack]}`;
  const count = document.createElement("div");
  count.textContent =
    learningLessons.length > 0 ? `${learningLessons.length}` : "0";
  header.appendChild(title);
  header.appendChild(count);
  learningLessonsEl.appendChild(header);

  if (!learningLessons.length) {
    const empty = document.createElement("div");
    empty.className = "learning-empty";
    empty.innerHTML = `Dépose tes fichiers Markdown dans <code>learning-content/</code> puis référence-les dans <code>manifest.json</code> (clé <code>lessons</code>).`;
    learningLessonsEl.appendChild(empty);
    return;
  }

  learningLessons.forEach((lesson, idx) => {
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "lesson-item";
    if (lesson.id === learningCurrentLessonId) {
      btn.classList.add("active");
    }
    const labelId = String(idx + 1).padStart(2, "0");
    btn.textContent = `${labelId} - ${lesson.title}`;
    btn.addEventListener("click", () => {
      selectLearningLesson(lesson.id);
    });
    learningLessonsEl.appendChild(btn);
  });
}

async function loadLearningManifest() {
  learningManifest = revisionCatalog;
  learningLessons = revisionCatalog.lessons
    .filter((lesson) => (lesson.track || "go") === currentTrack)
    .map(normalizeLesson)
    .filter(Boolean);
}

async function loadLearningData() {
  await loadLearningManifest();
  learningLoaded = true;
}

async function revisionMarkdown(lesson) {
  if (typeof learningLessonCache[lesson.id] === "string")
    return learningLessonCache[lesson.id];
  const text = await fetchTextResource(lesson.path);
  learningLessonCache[lesson.id] = text;
  return text;
}

async function selectLearningLesson(lessonId) {
  const lesson = learningLessons.find(
    (l) => l.id === lessonId || l.slug === slugify(lessonId || ""),
  );
  if (!lesson || !learningMode) return;
  const track = currentTrack;
  const request = ++learningRequestSequence;
  learningCurrentLessonId = lesson.id;
  learningSelections[track] = lesson.id;
  renderLearningLessons();
  learningContentEl.textContent = "Chargement de la fiche…";
  try {
    const md = await revisionMarkdown(lesson);
    if (
      request !== learningRequestSequence ||
      !learningMode ||
      currentTrack !== track
    )
      return;
    renderLearningContent(md);
  } catch (error) {
    if (
      request !== learningRequestSequence ||
      !learningMode ||
      currentTrack !== track
    )
      return;
    learningContentEl.textContent =
      "Impossible de charger la fiche. Réessaie ou vérifie que ses fichiers sont présents.";
  }
}

function normalizeLessonPath(p) {
  return decodeURIComponent((p || "").replace(/^\/+/, "").replace(/\\/g, "/"));
}

function findLessonByHref(href) {
  if (!href) return null;
  let url;
  try {
    url = new URL(href, window.location.href);
  } catch {
    return null;
  }
  // Anchor-only links like #structure-dun-fichier-go
  if (href.startsWith("#")) {
    const frag = href.replace(/^#/, "");
    const targetSlug = slugify(decodeURIComponent(frag));
    return learningLessons.find(
      (lesson) =>
        lesson.slug === targetSlug ||
        slugify(lesson.title) === targetSlug ||
        slugify(lesson.id) === targetSlug,
    );
  }

  const pathFromUrl = normalizeLessonPath(url.pathname);
  const filename = pathFromUrl.split("/").pop();
  return learningLessons.find((lesson) => {
    const lp = normalizeLessonPath(lesson.path);
    const lFile = lp.split("/").pop();
    return lp === pathFromUrl || lFile === filename || lesson.id === href;
  });
}

function setLearningMode(enabled) {
  learningMode = !!enabled;
  renderTrainingGuide(learningMode ? null : currentExercise);
  if (learningMode) {
    document.getElementById("exam-lobby").hidden = true;
    document.getElementById("exam-report").hidden = true;
    appEl.classList.remove("exam-setup", "exam-complete");
    editorIdentity = null;
    codeEditorEl.value = "";
    updateHighlight();
    outputEl.textContent = "";
  }
  document.querySelector(".catalog-panel").inert = learningMode;
  if (learningMode) {
    examTitleEl.textContent = "Fiches de révision";
    document.getElementById("exercise-level").textContent = "Apprendre";
  } else if (currentExercise) updateExerciseHeader(currentExercise);
  if (appEl) {
    appEl.classList.toggle("learning-mode", learningMode);
  } else {
    document.body.classList.toggle("learning-mode", learningMode);
  }
  updateModeLabel();
  learningRequestSequence++;
  if (learningMode) {
    const track = currentTrack;
    loadLearningData().then(() => {
      if (!learningMode || currentTrack !== track) return;
      learningCurrentLessonId = learningSelections[track] || null;
      renderLearningLessons();
      const target =
        learningLessons.find((l) => l.id === learningCurrentLessonId) ||
        learningLessons[0];
      if (target) selectLearningLesson(target.id);
      else renderLearningContent(defaultLessonMsg);
    });
  } else renderLearningContent(defaultLessonMsg);
}

/* Source: frontend/app/catalog-loader.js */
async function loadExercises() {
  try {
    const [goRes, jsRes, rustRes, javaRes] = await Promise.all([
      fetch("/api/exercises"),
      fetch("/api/exercises?track=js"),
      fetch("/api/exercises?track=rust"),
      fetch("/api/exercises?track=java"),
    ]);
    if (!goRes.ok) {
      outputEl.textContent =
        "Erreur chargement exercices Go: HTTP " + goRes.status;
      return;
    }
    exercises = await goRes.json();
    exercises.forEach((ex) => {
      ex.level = getExerciseLevel(exId(ex));
    });
    if (jsRes.ok) {
      const incomingJs = await jsRes.json();
      jsExercises = incomingJs.map((ex) => ({
        ...ex,
        level: Number.isInteger(ex.level) && ex.level > 0 ? ex.level : null,
      }));
    } else {
      jsExercises = [];
      console.warn(
        "Chargement des exercices JS impossible: HTTP",
        jsRes.status,
      );
    }
    if (rustRes.ok) {
      const incomingRust = await rustRes.json();
      rustExercises = incomingRust.map((ex) => ({
        ...ex,
        level: Number.isInteger(ex.level) && ex.level > 0 ? ex.level : null,
      }));
    } else {
      rustExercises = [];
      console.warn(
        "Chargement des exercices Rust impossible: HTTP",
        rustRes.status,
      );
    }
    if (javaRes.ok) {
      const incomingJava = await javaRes.json();
      javaExercises = incomingJava.map((ex) => ({
        ...ex,
        level: Number.isInteger(ex.level) && ex.level > 0 ? ex.level : null,
      }));
    } else {
      javaExercises = [];
      console.warn(
        "Chargement des exercices Java impossible: HTTP",
        javaRes.status,
      );
    }
    const saved = personalStore.session(currentTrack);
    if (currentTrack === "java") restoreJavaCheckpoints(saved);
    examKind = saved?.examKind === "strict" ? "strict" : "free";
    personalReady = true;
    if (saved) {
      currentLevelFilter = saved.filter || "all";
      setAppMode(saved.mode || "exam");
      currentLevelFilter = saved.filter || "all";
    }
    renderLevelFilters();
    renderChips();
    updateTrueExamControls();
    const source = getTrackExercises();
    if (!pathMode && !learningMode && !trueExamMode && source.length) {
      const target = saved && source.find((ex) => exId(ex) === saved.selected);
      selectExercise(exId(target || source[0]));
    } else if (trueExamMode && !trueExamSeries.length) {
      startTrueExamSeries();
    }
    savePersonalSession();
  } catch (e) {
    outputEl.textContent = "Erreur chargement exercices: " + e.message;
  }
}

